package collaborationrun
import("errors";"net/http";"net/http/httptest";"strings";"testing")
func TestFinalReviewConflictingFieldCaseMustRefuseLaunch(t *testing.T){
 h:=newLaunchHandoffFixture(t,"result")
 h.envelope.Sources[1].Truncated=true
 h.envelope.Sources[1].Content="Only the first part of the admitted delegation."
 original:=h.server.Config.Handler
 h.server.Config.Handler=http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
  if r.URL.Path!=runPath(h.claim.Identity.RunID,"handoff/snapshots"){original.ServeHTTP(w,r);return}
  response:=httptest.NewRecorder();original.ServeHTTP(response,r)
  raw:=strings.Replace(response.Body.String(),`"truncated":true`,`"truncated":true,"TRUNCATED":false`,1)
  if raw==response.Body.String(){t.Error("fixture did not contain a truncated delegation")}
  _,_=w.Write([]byte(raw))
 })
 err:=h.runner.Run(t.Context(),h.claim.Identity.RunID,h.request)
 starts:=len(h.starts(t));bindings:=len(h.bindings)
 t.Logf("case-aliased wire: starts=%d bindings=%d protocol_error=%t",starts,bindings,errors.Is(err,ErrProtocol))
 if !errors.Is(err,ErrProtocol)||starts!=0||bindings!=0{t.Error("conflicting case alias bypassed mandatory delegation completeness")}
}
